const LAST_TAB_EXIT_TIMEOUT_MS = 5_000;

export type WorkspaceState = {
  worktrees: Worktree[];
  activeWorktreePath: string | null;
  sessions: Record<string, TerminalSession>;
  layout: LayoutState;
  unreadTabIds: Record<string, boolean>;
  unreadWorktreePaths: Record<string, boolean>;
  /** Optional for backwards compatibility with persisted/test states created before activity tracking. */
  activityBySessionId?: Record<string, TerminalActivity>;
};

export type WorkspaceServices = {
  ensureTerminalEvents: () => Promise<void>;
  spawnTerminal: (request: { workspaceId: string; worktree: WorktreeIdentity | null; cwd?: string | null }) => Promise<string>;
  getTerminalCwd: (sessionId: string) => Promise<string | null>;
  closeTerminal: (sessionId: string) => Promise<void>;
  waitForTerminalExit: (sessionId: string, timeoutMs: number) => Promise<void>;
};

export type SplitPaneOptions = {
  position?: "first" | "second";
};

export type TabSplitEdge = "left" | "right" | "top" | "bottom";

type WorkspaceAction =
  | { type: "SET_WORKTREES"; worktrees: Worktree[] }
  | { type: "RESTORE_WORKSPACE"; state: WorkspaceState }
  | { type: "SELECT_WORKTREE"; path: string }
  | { type: "ADD_TAB_WITH_SESSION"; tab: WorkspaceTab; session?: TerminalSession }
  | {
      type: "CLOSE_TAB";
      tabId: string;
      replacement?: { tab: WorkspaceTab; session?: TerminalSession };
    }
  | { type: "UPDATE_BROWSER_TAB"; tabId: string; updates: Partial<BrowserTab> }
  | { type: "ACTIVATE_TAB"; tabId: string }
  | { type: "REORDER_TAB"; tabId: string; targetIndex: number }
  | { type: "RENAME_TAB"; tabId: string; label: string }
  | { type: "SET_TAB_PINNED"; tabId: string; pinned: boolean }
  | {
      type: "SPLIT_PANE";
      tabId: string;
      targetLeafId?: string;
      direction: PaneDirection;
      position?: "first" | "second";
      newLeafId: string;
      session: TerminalSession;
    }
  | { type: "MOVE_TAB_TO_GROUP"; sourceTabId: string; targetGroupId: string; targetIndex?: number }
  | {
      type: "MOVE_TAB_TO_SPLIT";
      sourceTabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position?: "first" | "second";
    }
  | {
      type: "MOVE_TAB_TO_PANE_SPLIT";
      sourceTabId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position?: "first" | "second";
    }
  | {
      type: "DETACH_PANE_TO_TAB";
      sourceTabId: string;
      leafId: string;
      newTab: TerminalTab;
      targetGroupId?: string;
      targetIndex?: number;
    }
  | {
      type: "CLOSE_PANE";
      tabId: string;
      leafId: string;
    }
  | { type: "FOCUS_PANE"; tabId: string; leafId: string }
  | { type: "SET_PANE_RATIO"; tabId: string; path: string; ratio: number }
  | { type: "SET_TAB_GROUP_RATIO"; path: string; ratio: number }
  | { type: "SWAP_PANES"; tabId: string; sourceLeafId: string; targetLeafId: string }
  | { type: "SESSION_LIFECYCLE"; backendSessionId: string; lifecycle: TerminalLifecycle }
  | { type: "SESSION_TITLE_ACTIVITY"; tabId: string; sessionId: string; title: string }
  | { type: "MARK_TAB_UNREAD"; tabId: string }
  | { type: "CLEAR_TAB_UNREAD"; tabId: string }
  | { type: "MARK_WORKTREE_UNREAD"; worktreePath: string }
  | { type: "CLEAR_WORKTREE_UNREAD"; worktreePath: string };

type UseWorkspaceStoreOptions = {
  workspaceId?: string;
  initialWorktrees?: Worktree[];
  services?: WorkspaceServices;
};

const defaultServices: WorkspaceServices = {
  ensureTerminalEvents,
  spawnTerminal,
  getTerminalCwd,
  closeTerminal,
  waitForTerminalExit,
};

export function useWorkspaceStore({
  workspaceId = DEFAULT_WORKSPACE_ID,
  initialWorktrees = [],
  services = defaultServices,
}: UseWorkspaceStoreOptions = {}) {
  const [state, reactDispatch] = useReducer(workspaceReducer, initialWorktrees, createInitialState);
  const stateRef = useRef(state);
  stateRef.current = state;

  const dispatch = useCallback((action: WorkspaceAction) => {
    stateRef.current = workspaceReducer(stateRef.current, action);
    reactDispatch(action);
  }, []);

  useEffect(() => {
    const unsubscribeLifecycle = terminalEventBus.subscribeLifecycle((payload) => {
      dispatch({
        type: "SESSION_LIFECYCLE",
        backendSessionId: payload.sessionId,
        lifecycle: mapBackendLifecycle(payload),
      });
    });
    const unsubscribeTitle = terminalEventBus.subscribeTitle((backendSessionId, title) => {
      const snapshot = stateRef.current;
      const session = Object.values(snapshot.sessions).find(
        (candidate) => candidate.backendSessionId === backendSessionId,
      );
      if (!session) return;
      const tabId = findTabIdForSession(snapshot, session.id);
      if (!tabId) return;
      dispatch({ type: "SESSION_TITLE_ACTIVITY", tabId, sessionId: session.id, title });
    });

    return () => {
      unsubscribeLifecycle();
      unsubscribeTitle();
    };
  }, [dispatch]);

  const createSpawnedTab = useCallback(
    async (worktree: Worktree, label?: string, backendSessionIdOverride?: string) => {
      await services.ensureTerminalEvents();
      const backendSessionId =
        backendSessionIdOverride ??
        (await services.spawnTerminal({
          workspaceId,
          worktree: worktreeIdentity(worktree),
          cwd: worktree.path,
        }));
      const sessionId = createId("session");
      const tabId = createId("tab");
      const session: TerminalSession = {
        id: sessionId,
        cwd: worktree.path,
        worktreePath: worktree.path,
        workspaceId,
        worktree: worktreeIdentity(worktree),
        backendSessionId,
        lifecycle: "working",
      };
      const tab: TerminalTab = {
        id: tabId,
        label: label ?? nextTabLabel(worktree, stateRef.current.layout.tabs, stateRef.current.sessions),
        sessionId,
      };
      return { tab, session };
    },
    [services, workspaceId],
  );

  const openTab = useCallback(
    async (worktree: Worktree, label?: string, backendSessionIdOverride?: string) => {
      const binding = await createSpawnedTab(worktree, label, backendSessionIdOverride);
      dispatch({ type: "ADD_TAB_WITH_SESSION", ...binding });
      if (!stateRef.current.worktrees.some((candidate) => candidate.path === worktree.path)) {
        dispatch({ type: "SET_WORKTREES", worktrees: [...stateRef.current.worktrees, worktree] });
      }
      dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
      return binding.tab.id;
    },
    [createSpawnedTab, dispatch],
  );

  const ensureTabForWorktree = useCallback(
    async (worktree: Worktree) => {
      const snapshot = stateRef.current;
      const existing = snapshot.layout.tabs.find(
        (tab) => tab.kind !== "browser" && sessionWorktreePath(snapshot.sessions[tab.sessionId]) === worktree.path,
      );
      dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
      if (existing) {
        dispatch({ type: "ACTIVATE_TAB", tabId: existing.id });
        return existing.id;
      }
      return openTab(worktree);
    },
    [dispatch, openTab],
  );

  const splitPane = useCallback(
    async (
      tabId: string,
      targetLeafId: string,
      direction: PaneDirection,
      options: SplitPaneOptions = {},
    ) => {
      const snapshot = stateRef.current;
      const targetTab = snapshot.layout.tabs.find((candidate) => candidate.id === tabId);
      if (!targetTab || targetTab.kind === "browser") return;
      const targetLayout = snapshot.layout.layoutsByTabId?.[targetTab.id];
      if (!targetLayout || !collectLeafIds(targetLayout.root).includes(targetLeafId)) return;

      const sourceLocalSessionId = targetLayout.sessionIdsByLeafId[targetLeafId] ?? targetTab.sessionId;
      const sourceSession = snapshot.sessions[sourceLocalSessionId];
      if (!sourceSession) return;

      await services.ensureTerminalEvents();
      let inheritedCwd = sourceSession.cwd;
      if (sourceSession.backendSessionId) {
        try {
          inheritedCwd = (await services.getTerminalCwd(sourceSession.backendSessionId)) ?? sourceSession.cwd;
        } catch {
          inheritedCwd = sourceSession.cwd;
        }
      }

      const backendSessionId = await services.spawnTerminal({
        workspaceId,
        worktree: sourceSession.worktree,
        cwd: inheritedCwd,
      });
      const localSessionId = createId("session");
      const newLeafId = createId("leaf");
      const session: TerminalSession = {
        id: localSessionId,
        cwd: inheritedCwd,
        worktreePath: sessionWorktreePath(sourceSession),
        workspaceId: sourceSession.workspaceId || workspaceId,
        worktree: sourceSession.worktree,
        backendSessionId,
        lifecycle: "working",
      };

      dispatch({
        type: "SPLIT_PANE",
        tabId: targetTab.id,
        targetLeafId,
        direction,
        position: options.position,
        newLeafId,
        session,
      });

      if (!stateRef.current.sessions[localSessionId]) {
        terminalEventBus.clearSession(backendSessionId);
        await services.closeTerminal(backendSessionId).catch(() => undefined);
      }
    },
    [dispatch, services, workspaceId],
  );

  const moveTabToGroup = useCallback(
    (sourceTabId: string, targetGroupId: string, targetIndex?: number) => {
      dispatch({ type: "MOVE_TAB_TO_GROUP", sourceTabId, targetGroupId, targetIndex });
    },
    [dispatch],
  );

  const moveTabToSplit = useCallback(
    (
      sourceTabId: string,
      targetGroupId: string,
      direction: PaneDirection,
      position: "first" | "second" = "second",
      targetPane?: { tabId: string; leafId: string },
    ) => {
      if (targetPane) {
        dispatch({
          type: "MOVE_TAB_TO_PANE_SPLIT",
          sourceTabId,
          targetTabId: targetPane.tabId,
          targetLeafId: targetPane.leafId,
          direction,
          position,
        });
      } else {
        dispatch({ type: "MOVE_TAB_TO_SPLIT", sourceTabId, targetGroupId, direction, position });
      }
    },
    [dispatch],
  );

  const detachPaneToTab = useCallback(
    (sourceTabId: string, leafId: string, targetGroupId?: string, targetIndex?: number) => {
      const snapshot = stateRef.current;
      const sourceTab = snapshot.layout.tabs.find((tab) => tab.id === sourceTabId);
      const sourceLayout = snapshot.layout.layoutsByTabId[sourceTabId];
      if (!sourceTab || sourceTab.kind === "browser" || !sourceLayout || collectLeafIds(sourceLayout.root).length <= 1) return null;
      const sessionId = sourceLayout.sessionIdsByLeafId[leafId];
      if (!sessionId || !snapshot.sessions[sessionId]) return null;
      const newTabId = createId("tab");
      const newTab: TerminalTab = {
        id: newTabId,
        label: sourceTab.label,
        sessionId,
      };
      dispatch({ type: "DETACH_PANE_TO_TAB", sourceTabId, leafId, newTab, targetGroupId, targetIndex });
      return stateRef.current.layout.tabs.some((tab) => tab.id === newTabId) ? newTabId : null;
    },
    [dispatch],
  );

  const closeTab = useCallback(
    async (tabId: string) => {
      const snapshot = stateRef.current;
      const closingTab = snapshot.layout.tabs.find((tab) => tab.id === tabId);
      if (!closingTab || closingTab.pinned) return;

      if (closingTab.kind === "browser") {
        await closeBrowser(closingTab.browserId);
        dispatch({ type: "CLOSE_TAB", tabId });
        return;
      }

      const closingSession = snapshot.sessions[closingTab.sessionId];
      const disposableSessions = getDisposableSessionsForTab(snapshot, tabId);
      const tabSessionIds = getTabSessionIds(snapshot, tabId);

      if (snapshot.layout.tabs.length === 1) {
        const closingWorktreePath = sessionWorktreePath(closingSession);
        const worktree =
          (closingWorktreePath && snapshot.worktrees.find((candidate) => candidate.path === closingWorktreePath)) ??
          getActiveWorktree(snapshot);
        if (!worktree) return;

        await Promise.all(
          disposableSessions.map((session) => closeBackendSessionAndWait(session, services)),
        );
        for (const sessionId of tabSessionIds) {
          if (!isSessionReferencedOutsideTab(snapshot, sessionId, tabId)) {
            terminalHostManager.destroy(sessionId);
          }
        }
        const replacement = await createSpawnedTab(worktree, closingTab.label);
        dispatch({ type: "CLOSE_TAB", tabId, replacement });
        return;
      }

      dispatch({ type: "CLOSE_TAB", tabId });
      for (const sessionId of tabSessionIds) {
        if (!isSessionReferencedOutsideTab(snapshot, sessionId, tabId)) {
          terminalHostManager.destroy(sessionId);
        }
      }
      await Promise.allSettled(disposableSessions.map((session) => closeBackendSession(session, services)));
    },
    [createSpawnedTab, dispatch, services],
  );

  const closePane = useCallback(
    async (tabId: string, leafId: string) => {
      const snapshot = stateRef.current;
      const tabLayout = snapshot.layout.layoutsByTabId?.[tabId];
      if (!tabLayout) return;
      if (tabLayout.root.type === "leaf") {
        if (tabLayout.root.leafId === leafId) await closeTab(tabId);
        return;
      }

      const closingSessionId = tabLayout.sessionIdsByLeafId[leafId];
      const closingSession = closingSessionId ? snapshot.sessions[closingSessionId] : undefined;
      dispatch({ type: "CLOSE_PANE", tabId, leafId });
      if (closingSessionId && !isSessionReferenced(stateRef.current, closingSessionId)) {
        terminalHostManager.destroy(closingSessionId);
        await closeBackendSession(closingSession, services);
      }
    },
    [closeTab, dispatch, services],
  );

  const closeTabs = useCallback(
    async (tabIds: string[]) => {
      for (const tabId of tabIds) await closeTab(tabId);
    },
    [closeTab],
  );

  const closeOtherTabs = useCallback(
    async (tabId: string) => {
      const snapshot = stateRef.current;
      const group = getGroupForTab(snapshot.layout, tabId);
      const tabs = group ? getTabsForGroup(snapshot.layout, group.id) : [];
      await closeTabs(tabs.filter((tab) => tab.id !== tabId && !tab.pinned).map((tab) => tab.id));
    },
    [closeTabs],
  );

  const closeTabsToRight = useCallback(
    async (tabId: string) => {
      const snapshot = stateRef.current;
      const group = getGroupForTab(snapshot.layout, tabId);
      const tabs = group ? getTabsForGroup(snapshot.layout, group.id) : [];
      const index = tabs.findIndex((tab) => tab.id === tabId);
      if (index < 0) return;
      await closeTabs(tabs.slice(index + 1).filter((tab) => !tab.pinned).map((tab) => tab.id));
    },
    [closeTabs],
  );

  const closeTabsToLeft = useCallback(
    async (tabId: string) => {
      const snapshot = stateRef.current;
      const group = getGroupForTab(snapshot.layout, tabId);
      const tabs = group ? getTabsForGroup(snapshot.layout, group.id) : [];
      const index = tabs.findIndex((tab) => tab.id === tabId);
      if (index < 0) return;
      await closeTabs(tabs.slice(0, index).filter((tab) => !tab.pinned).map((tab) => tab.id));
    },
    [closeTabs],
  );

  const syncWorktrees = useCallback(
    async (worktrees: Worktree[]) => {
      const snapshot = stateRef.current;
      const validWorktreePaths = new Set(worktrees.map((worktree) => worktree.path));
      const staleSessions = Object.values(snapshot.sessions).filter((session) => !validWorktreePaths.has(sessionWorktreePath(session)));
      dispatch({ type: "SET_WORKTREES", worktrees });
      for (const session of staleSessions) {
        terminalHostManager.destroy(session.id);
      }
      await Promise.allSettled(staleSessions.map((session) => closeBackendSession(session, services)));
    },
    [dispatch, services],
  );

  const activateTab = useCallback((tabId: string) => dispatch({ type: "ACTIVATE_TAB", tabId }), [dispatch]);
  const reorderTab = useCallback(
    (tabId: string, targetIndex: number) => dispatch({ type: "REORDER_TAB", tabId, targetIndex }),
    [dispatch],
  );
  const renameTab = useCallback(
    (tabId: string, label: string) => dispatch({ type: "RENAME_TAB", tabId, label }),
    [dispatch],
  );
  const setTabPinned = useCallback(
    (tabId: string, pinned: boolean) => dispatch({ type: "SET_TAB_PINNED", tabId, pinned }),
    [dispatch],
  );
  const focusPane = useCallback((tabId: string, leafId: string) => dispatch({ type: "FOCUS_PANE", tabId, leafId }), [dispatch]);
  const setPaneRatio = useCallback(
    (tabId: string, path: string, ratio: number) => dispatch({ type: "SET_PANE_RATIO", tabId, path, ratio }),
    [dispatch],
  );
  const setTabGroupRatio = useCallback(
    (path: string, ratio: number) => dispatch({ type: "SET_TAB_GROUP_RATIO", path, ratio }),
    [dispatch],
  );
  const swapPanes = useCallback(
    (tabId: string, sourceLeafId: string, targetLeafId: string) => dispatch({ type: "SWAP_PANES", tabId, sourceLeafId, targetLeafId }),
    [dispatch],
  );

  const restoreWorkspace = useCallback(
    (restoredState: WorkspaceState) => dispatch({ type: "RESTORE_WORKSPACE", state: restoredState }),
    [dispatch],
  );

  const updateSessionTitleActivity = useCallback(
    (tabId: string, title: string, explicitSessionId?: string) => {
      const snapshot = stateRef.current;
      const tab = snapshot.layout.tabs.find((candidate) => candidate.id === tabId);
      if (!tab || tab.kind === "browser") return;
      const sessionId = explicitSessionId ?? tab.sessionId;
      if (!snapshot.sessions[sessionId]) return;
      dispatch({ type: "SESSION_TITLE_ACTIVITY", tabId, sessionId, title });
    },
    [dispatch],
  );

  const createBrowserTab = useCallback(
    async (url = "http://localhost:3000", label?: string) => {
      const activeWorktree = getActiveWorktree(stateRef.current);
      const browserState = await createBrowser({
        workspaceId,
        worktreePath: activeWorktree?.path,
        url,
        visible: true,
      });

      const tabId = createId("tab");
      const browserTab: BrowserTab = {
        kind: "browser",
        id: tabId,
        label: label ?? "Browser",
        browserId: browserState.browserId,
        url: browserState.url,
        title: browserState.title,
        loading: browserState.loading,
        canGoBack: browserState.canGoBack,
        canGoForward: browserState.canGoForward,
      };

      dispatch({ type: "ADD_TAB_WITH_SESSION", tab: browserTab });
      return tabId;
    },
    [dispatch, workspaceId],
  );

  const navigateBrowserTabAction = useCallback(
    async (tabId: string, url: string) => {
      const tab = stateRef.current.layout.tabs.find((candidate) => candidate.id === tabId);
      if (!tab || tab.kind !== "browser") return;
      dispatch({ type: "UPDATE_BROWSER_TAB", tabId, updates: { url, loading: true } });
      try {
        await navigateBrowser(tab.browserId, url);
      } finally {
        if (stateRef.current.layout.tabs.some((candidate) => candidate.id === tabId)) {
          dispatch({ type: "UPDATE_BROWSER_TAB", tabId, updates: { loading: false } });
        }
      }
    },
    [dispatch],
  );

  const reloadBrowserTabAction = useCallback(
    async (tabId: string) => {
      const tab = stateRef.current.layout.tabs.find((candidate) => candidate.id === tabId);
      if (!tab || tab.kind !== "browser") return;
      dispatch({ type: "UPDATE_BROWSER_TAB", tabId, updates: { loading: true } });
      try {
        await reloadBrowser(tab.browserId);
      } finally {
        if (stateRef.current.layout.tabs.some((candidate) => candidate.id === tabId)) {
          dispatch({ type: "UPDATE_BROWSER_TAB", tabId, updates: { loading: false } });
        }
      }
    },
    [dispatch],
  );

  const openWorkspacePortInBrowser = useCallback(
    async (port: number) => {
      const url = `http://localhost:${port}`;
      return createBrowserTab(url, `Port ${port}`);
    },
    [createBrowserTab],
  );

  return {
    state,
    agents: selectAgents(state),
    tabActivity: selectTabActivitySummaries(state),
    worktreeActivity: selectWorktreeActivitySummaries(state),
    openTab,
    createBrowserTab,
    navigateBrowserTab: navigateBrowserTabAction,
    reloadBrowserTab: reloadBrowserTabAction,
    ensureTabForWorktree,
    openWorkspacePortInBrowser,
    closeTab,
    closeOtherTabs,
    closeTabsToRight,
    closeTabsToLeft,
    splitPane,
    moveTabToGroup,
    moveTabToSplit,
    detachPaneToTab,
    closePane,
    activateTab,
    reorderTab,
    renameTab,
    setTabPinned,
    focusPane,
    setPaneRatio,
    setTabGroupRatio,
    swapPanes,
    syncWorktrees,
    restoreWorkspace,
    updateSessionTitleActivity,
    markTabUnread: (tabId: string) => dispatch({ type: "MARK_TAB_UNREAD", tabId }),
    clearTabUnread: (tabId: string) => dispatch({ type: "CLEAR_TAB_UNREAD", tabId }),
    markWorktreeUnread: (worktreePath: string) => dispatch({ type: "MARK_WORKTREE_UNREAD", worktreePath }),
    clearWorktreeUnread: (worktreePath: string) => dispatch({ type: "CLEAR_WORKTREE_UNREAD", worktreePath }),
  };
}

export function selectAgents(state: WorkspaceState): ActiveAgent[] {
  return state.layout.tabs.flatMap((tab) => {
    if (tab.kind === "browser") return [];
    const session = state.sessions[tab.sessionId];
    if (!session) return [];
    const worktreePath = sessionWorktreePath(session);
    const worktree = state.worktrees.find((candidate) => candidate.path === worktreePath);
    const activity = state.activityBySessionId?.[session.id];
    const parsed = activity ? parseAgentTitle(activity.title) : null;
    return [
      {
        id: session.backendSessionId ?? session.id,
        name: parsed?.isAgent ? parsed.name : tab.label,
        task: parsed?.isAgent
          ? parsed.task
          : worktree?.branch?.replace(/^refs\/heads\//, "") ?? worktreePath,
        state: activity ? activityStateToAgentState(activity.state) : session.lifecycle,
        worktree: session.worktree,
        worktreePath,
        sessionId: session.backendSessionId ?? session.id,
      },
    ];
  });
}

export function selectTabActivitySummaries(state: WorkspaceState): Record<string, ActivitySummary> {
  const result: Record<string, ActivitySummary> = {};
  const activityBySessionId = state.activityBySessionId ?? {};

  for (const tab of state.layout.tabs) {
    if (tab.kind === "browser") continue;
    const sessionIds = getTabSessionIds(state, tab.id);
    const activities = [...sessionIds]
      .map((sessionId) => activityBySessionId[sessionId])
      .filter((activity): activity is TerminalActivity => Boolean(activity));
    result[tab.id] = summarizeActivities(activities, Boolean(state.unreadTabIds[tab.id]));
  }

  return result;
}

export function selectWorktreeActivitySummaries(state: WorkspaceState): Record<string, ActivitySummary> {
  const result: Record<string, ActivitySummary> = {};
  const activityBySessionId = state.activityBySessionId ?? {};
  const sessionIdsByWorktree = new Map<string, Set<string>>();
  const unreadTabsByWorktree = new Set<string>();

  for (const tab of state.layout.tabs) {
    if (tab.kind === "browser") continue;
    const sessionIds = getTabSessionIds(state, tab.id);
    const worktreePaths = new Set<string>();
    for (const sessionId of sessionIds) {
      const session = state.sessions[sessionId];
      if (!session) continue;
      const worktreePath = sessionWorktreePath(session);
      worktreePaths.add(worktreePath);
      const bucket = sessionIdsByWorktree.get(worktreePath) ?? new Set<string>();
      bucket.add(sessionId);
      sessionIdsByWorktree.set(worktreePath, bucket);
    }
    if (state.unreadTabIds[tab.id]) {
      for (const path of worktreePaths) unreadTabsByWorktree.add(path);
    }
  }

  for (const worktree of state.worktrees) {
    const sessionIds = sessionIdsByWorktree.get(worktree.path) ?? new Set<string>();
    const activities = [...sessionIds]
      .map((sessionId) => activityBySessionId[sessionId])
      .filter((activity): activity is TerminalActivity => Boolean(activity));
    result[worktree.path] = summarizeActivities(
      activities,
      Boolean(state.unreadWorktreePaths[worktree.path] || unreadTabsByWorktree.has(worktree.path)),
    );
  }

  return result;
}

function createInitialState(worktrees: Worktree[]): WorkspaceState {
  return {
    worktrees,
    activeWorktreePath: worktrees[0]?.path ?? null,
    sessions: {},
    layout: createLayoutState(),
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

function workspaceReducer(state: WorkspaceState, action: WorkspaceAction): WorkspaceState {
  switch (action.type) {
    case "RESTORE_WORKSPACE":
      return {
        ...action.state,
        unreadTabIds: action.state.unreadTabIds ?? {},
        unreadWorktreePaths: action.state.unreadWorktreePaths ?? {},
        activityBySessionId: action.state.activityBySessionId ?? {},
      };
    case "SET_WORKTREES": {
      const validWorktreePaths = new Set(action.worktrees.map((worktree) => worktree.path));
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).filter(([, session]) => validWorktreePaths.has(sessionWorktreePath(session))),
      );
      const activityBySessionId = Object.fromEntries(
        Object.entries(state.activityBySessionId ?? {}).filter(([sessionId]) => Boolean(sessions[sessionId])),
      );
      let layout = state.layout;
      for (const tab of state.layout.tabs) {
        const hasRetainedSession = [...getTabSessionIds(state, tab.id)].some((sessionId) => Boolean(sessions[sessionId]));
        if (tab.kind !== "browser" && !hasRetainedSession) {
          layout = layoutReducer(layout, { type: "CLOSE_TAB", tabId: tab.id });
        }
      }
      const activeWorktreePath = action.worktrees.some((worktree) => worktree.path === state.activeWorktreePath)
        ? state.activeWorktreePath
        : action.worktrees[0]?.path ?? null;
      const unreadTabIds = Object.fromEntries(
        Object.entries(state.unreadTabIds).filter(([tabId]) => layout.tabs.some((tab) => tab.id === tabId)),
      );
      const unreadWorktreePaths = Object.fromEntries(
        Object.entries(state.unreadWorktreePaths).filter(([path]) => validWorktreePaths.has(path)),
      );
      return {
        ...state,
        worktrees: action.worktrees,
        activeWorktreePath,
        sessions,
        layout,
        activityBySessionId,
        unreadTabIds,
        unreadWorktreePaths,
      };
    }
    case "UPDATE_BROWSER_TAB": {
      const tabs = state.layout.tabs.map((tab) => {
        if (tab.id === action.tabId && tab.kind === "browser") return { ...tab, ...action.updates };
        return tab;
      });
      return { ...state, layout: { ...state.layout, tabs } };
    }
    case "SELECT_WORKTREE": {
      if (!state.worktrees.some((worktree) => worktree.path === action.path)) return state;
      const unreadWorktreePaths = { ...state.unreadWorktreePaths };
      delete unreadWorktreePaths[action.path];
      const unreadTabIds = { ...state.unreadTabIds };
      for (const tab of state.layout.tabs) {
        if (getTabWorktreePath(state, tab.id) === action.path) delete unreadTabIds[tab.id];
      }
      return { ...state, activeWorktreePath: action.path, unreadTabIds, unreadWorktreePaths };
    }
    case "MARK_TAB_UNREAD": {
      if (action.tabId === state.layout.activeTabId) return state;
      const worktreePath = getTabWorktreePath(state, action.tabId);
      return {
        ...state,
        unreadTabIds: { ...state.unreadTabIds, [action.tabId]: true },
        unreadWorktreePaths: worktreePath
          ? { ...state.unreadWorktreePaths, [worktreePath]: true }
          : state.unreadWorktreePaths,
      };
    }
    case "CLEAR_TAB_UNREAD": {
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.tabId];
      return clearWorktreeUnreadWhenRead({ ...state, unreadTabIds }, action.tabId);
    }
    case "MARK_WORKTREE_UNREAD":
      return {
        ...state,
        unreadWorktreePaths: { ...state.unreadWorktreePaths, [action.worktreePath]: true },
      };
    case "CLEAR_WORKTREE_UNREAD": {
      const unreadWorktreePaths = { ...state.unreadWorktreePaths };
      delete unreadWorktreePaths[action.worktreePath];
      return { ...state, unreadWorktreePaths };
    }
    case "ADD_TAB_WITH_SESSION": {
      const sessions = action.session ? { ...state.sessions, [action.session.id]: action.session } : state.sessions;
      const sessionId = action.session?.id;
      return {
        ...state,
        sessions,
        layout: layoutReducer(state.layout, { type: "ADD_TAB", tab: action.tab, sessionId }),
      };
    }
    case "REORDER_TAB":
      return { ...state, layout: layoutReducer(state.layout, action) };
    case "RENAME_TAB":
      return { ...state, layout: layoutReducer(state.layout, action) };
    case "SET_TAB_PINNED":
      return { ...state, layout: layoutReducer(state.layout, action) };
    case "SPLIT_PANE": {
      const layout = layoutReducer(state.layout, {
        type: "SPLIT_PANE",
        tabId: action.tabId,
        targetLeafId: action.targetLeafId,
        direction: action.direction,
        position: action.position,
        newLeafId: action.newLeafId,
        sessionId: action.session.id,
      });
      if (layout === state.layout) return state;
      return {
        ...state,
        sessions: { ...state.sessions, [action.session.id]: action.session },
        layout,
      };
    }
    case "MOVE_TAB_TO_GROUP": {
      const layout = layoutReducer(state.layout, action);
      if (layout === state.layout) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.sourceTabId];
      return { ...state, layout, unreadTabIds };
    }
    case "MOVE_TAB_TO_SPLIT": {
      const layout = layoutReducer(state.layout, action);
      if (layout === state.layout) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.sourceTabId];
      return { ...state, layout, unreadTabIds };
    }
    case "MOVE_TAB_TO_PANE_SPLIT": {
      const layout = moveTabIntoPaneSplit(
        state.layout,
        action.sourceTabId,
        action.targetTabId,
        action.targetLeafId,
        action.direction,
        action.position,
      );
      if (layout === state.layout) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.sourceTabId];
      return { ...state, layout, unreadTabIds };
    }
    case "DETACH_PANE_TO_TAB": {
      const layout = layoutReducer(state.layout, action);
      if (layout === state.layout) return state;
      return { ...state, layout };
    }
    case "CLOSE_PANE": {
      const tab = state.layout.tabs.find((candidate) => candidate.id === action.tabId);
      const tabLayout = state.layout.layoutsByTabId?.[action.tabId];
      if (!tab || tab.kind === "browser" || !tabLayout) return state;
      if (tabLayout.root.type === "leaf" && tabLayout.root.leafId === action.leafId) {
        return workspaceReducer(state, { type: "CLOSE_TAB", tabId: action.tabId });
      }
      const closingSessionId = tabLayout.sessionIdsByLeafId[action.leafId];
      let layout = layoutReducer(state.layout, {
        type: "CLOSE_PANE",
        tabId: action.tabId,
        leafId: action.leafId,
      });
      if (layout === state.layout) return state;

      if (closingSessionId === tab.sessionId) {
        const remainingLayout = layout.layoutsByTabId[action.tabId];
        const replacementSessionId = Object.values(remainingLayout?.sessionIdsByLeafId ?? {}).find(Boolean);
        if (replacementSessionId && replacementSessionId !== tab.sessionId) {
          layout = {
            ...layout,
            tabs: layout.tabs.map((candidate) =>
              candidate.id === action.tabId && candidate.kind !== "browser"
                ? { ...candidate, sessionId: replacementSessionId }
                : candidate,
            ),
          };
        }
      }

      const candidateState: WorkspaceState = { ...state, layout };
      if (!closingSessionId || isSessionReferenced(candidateState, closingSessionId)) return candidateState;
      const sessions = { ...state.sessions };
      delete sessions[closingSessionId];
      const activityBySessionId = { ...(state.activityBySessionId ?? {}) };
      delete activityBySessionId[closingSessionId];
      return { ...candidateState, sessions, activityBySessionId };
    }
    case "CLOSE_TAB": {
      const closingSessionIds = getTabSessionIds(state, action.tabId);
      const sessions = { ...state.sessions };
      const activityBySessionId = { ...(state.activityBySessionId ?? {}) };
      for (const sessionId of closingSessionIds) {
        if (isSessionReferencedOutsideTab(state, sessionId, action.tabId)) continue;
        delete sessions[sessionId];
        delete activityBySessionId[sessionId];
      }
      if (action.replacement?.session) sessions[action.replacement.session.id] = action.replacement.session;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.tabId];
      const nextState = {
        ...state,
        sessions,
        activityBySessionId,
        unreadTabIds,
        layout: layoutReducer(state.layout, {
          type: "CLOSE_TAB",
          tabId: action.tabId,
          replacementTab: action.replacement?.tab,
        }),
      };
      return clearWorktreeUnreadWhenRead(nextState, action.tabId, state);
    }
    case "ACTIVATE_TAB": {
      if (!state.layout.tabs.some((tab) => tab.id === action.tabId)) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.tabId];
      const nextState = {
        ...state,
        unreadTabIds,
        layout: layoutReducer(state.layout, { type: "ACTIVATE_TAB", tabId: action.tabId }),
      };
      return clearWorktreeUnreadWhenRead(nextState, action.tabId, state);
    }
    case "FOCUS_PANE": {
      const layout = layoutReducer(state.layout, { type: "FOCUS_PANE", tabId: action.tabId, leafId: action.leafId });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SET_PANE_RATIO": {
      const layout = layoutReducer(state.layout, { type: "SET_PANE_RATIO", tabId: action.tabId, path: action.path, ratio: action.ratio });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SET_TAB_GROUP_RATIO": {
      const layout = layoutReducer(state.layout, { type: "SET_TAB_GROUP_RATIO", path: action.path, ratio: action.ratio });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SWAP_PANES": {
      const layout = layoutReducer(state.layout, { type: "SWAP_PANES", tabId: action.tabId, sourceLeafId: action.sourceLeafId, targetLeafId: action.targetLeafId });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SESSION_LIFECYCLE": {
      const matchedSessionIds: string[] = [];
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).map(([id, session]) => {
          if (session.backendSessionId !== action.backendSessionId) return [id, session];
          matchedSessionIds.push(id);
          return [id, { ...session, lifecycle: action.lifecycle }];
        }),
      ) as Record<string, TerminalSession>;
      let nextState: WorkspaceState = { ...state, sessions };
      if (action.lifecycle === "exited") {
        for (const sessionId of matchedSessionIds) {
          const current = nextState.activityBySessionId?.[sessionId];
          if (!current || current.state === "done") continue;
          const tabId = findTabIdForSession(nextState, sessionId);
          if (!tabId) continue;
          nextState = applySessionActivity(nextState, tabId, sessionId, { ...current, state: "done" });
        }
      }
      return nextState;
    }
    case "SESSION_TITLE_ACTIVITY": {
      const parsed = parseAgentTitle(action.title);
      const classified = classifyTerminalTitleActivity(action.title);

      if (!classified) {
        if (!state.activityBySessionId?.[action.sessionId]) return state;
        const activityBySessionId = { ...(state.activityBySessionId ?? {}) };
        delete activityBySessionId[action.sessionId];
        return { ...state, activityBySessionId };
      }

      const normalizedTitle = normalizeTerminalTitle(action.title);
      const activity: TerminalActivity = {
        state: classified,
        title: formatTabLabelFromTitle(action.title, normalizedTitle),
        isAgent: Boolean(parsed?.isAgent || classified),
        agentType: parsed?.isAgent ? parsed.agentType : undefined,
      };
      return applySessionActivity(state, action.tabId, action.sessionId, activity);
    }
  }
}

function applySessionActivity(
  state: WorkspaceState,
  tabId: string,
  sessionId: string,
  activity: TerminalActivity,
): WorkspaceState {
  const previous = state.activityBySessionId?.[sessionId];
  if (
    previous &&
    previous.state === activity.state &&
    previous.title === activity.title &&
    previous.isAgent === activity.isAgent &&
    previous.agentType === activity.agentType
  ) {
    return state;
  }

  let nextState: WorkspaceState = {
    ...state,
    activityBySessionId: { ...(state.activityBySessionId ?? {}), [sessionId]: activity },
  };

  if (activity.state === "done" && previous?.state !== "done" && tabId !== state.layout.activeTabId) {
    const worktreePath = sessionWorktreePath(state.sessions[sessionId]) || getTabWorktreePath(state, tabId);
    nextState = {
      ...nextState,
      unreadTabIds: { ...state.unreadTabIds, [tabId]: true },
      unreadWorktreePaths: worktreePath
        ? { ...state.unreadWorktreePaths, [worktreePath]: true }
        : state.unreadWorktreePaths,
    };
  }

  return nextState;
}

function getTabSessionIds(state: WorkspaceState, tabId: string): Set<string> {
  const tab = state.layout.tabs.find((candidate) => candidate.id === tabId);
  if (!tab || tab.kind === "browser") return new Set<string>();
  const tabLayout = state.layout.layoutsByTabId?.[tabId];
  const sessionIds = new Set<string>(Object.values(tabLayout?.sessionIdsByLeafId ?? {}));
  sessionIds.add(tab.sessionId);
  sessionIds.delete("");
  return sessionIds;
}

function isSessionReferencedOutsideTab(state: WorkspaceState, sessionId: string, tabId: string): boolean {
  return state.layout.tabs.some((tab) => tab.id !== tabId && getTabSessionIds(state, tab.id).has(sessionId));
}

function isSessionReferenced(state: WorkspaceState, sessionId: string): boolean {
  return state.layout.tabs.some((tab) => getTabSessionIds(state, tab.id).has(sessionId));
}

function getDisposableSessionsForTab(state: WorkspaceState, tabId: string): TerminalSession[] {
  const result: TerminalSession[] = [];
  const seenBackends = new Set<string>();
  for (const sessionId of getTabSessionIds(state, tabId)) {
    if (isSessionReferencedOutsideTab(state, sessionId, tabId)) continue;
    const session = state.sessions[sessionId];
    if (!session) continue;
    const key = session.backendSessionId ?? session.id;
    if (seenBackends.has(key)) continue;
    seenBackends.add(key);
    result.push(session);
  }
  return result;
}

function sessionWorktreePath(session: TerminalSession | undefined): string {
  return session?.worktreePath ?? session?.cwd ?? "";
}

function getTabWorktreePath(state: WorkspaceState, tabId: string): string | null {
  for (const sessionId of getTabSessionIds(state, tabId)) {
    const path = sessionWorktreePath(state.sessions[sessionId]);
    if (path) return path;
  }
  return null;
}

function findTabIdForSession(state: WorkspaceState, sessionId: string): string | null {
  for (const tab of state.layout.tabs) {
    if (tab.kind === "browser") continue;
    if (getTabSessionIds(state, tab.id).has(sessionId)) return tab.id;
  }
  return null;
}

function clearWorktreeUnreadWhenRead(
  state: WorkspaceState,
  tabId: string,
  sourceState: WorkspaceState = state,
): WorkspaceState {
  const worktreePath = getTabWorktreePath(sourceState, tabId);
  if (!worktreePath) return state;
  const hasOtherUnreadTab = sourceState.layout.tabs.some(
    (tab) => tab.id !== tabId && state.unreadTabIds[tab.id] && getTabWorktreePath(sourceState, tab.id) === worktreePath,
  );
  if (hasOtherUnreadTab) return state;
  const unreadWorktreePaths = { ...state.unreadWorktreePaths };
  delete unreadWorktreePaths[worktreePath];
  return { ...state, unreadWorktreePaths };
}

async function closeBackendSession(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  try {
    await services.closeTerminal(session.backendSessionId);
  } finally {
    terminalEventBus.clearSession(session.backendSessionId);
  }
}

async function closeBackendSessionAndWait(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  const backendSessionId = session.backendSessionId;
  const exitPromise = services.waitForTerminalExit(backendSessionId, LAST_TAB_EXIT_TIMEOUT_MS);
  try {
    await services.closeTerminal(backendSessionId);
    await exitPromise;
  } finally {
    terminalEventBus.clearSession(backendSessionId);
  }
}

function getActiveWorktree(state: WorkspaceState) {
  return state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? state.worktrees[0] ?? null;
}

function nextTabLabel(worktree: Worktree, tabs: WorkspaceTab[], sessions: Record<string, TerminalSession>) {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "") ?? "";
  const parts = branch.split("/");
  const base =
    parts[0] === "orca" && parts.length > 2
      ? parts.slice(2).join("/")
      : branch && branch !== "orca-lite"
        ? branch
        : "main";
  const count = tabs.filter(
    (tab) => tab.kind !== "browser" && sessionWorktreePath(sessions[tab.sessionId]) === worktree.path,
  ).length + 1;
  return count === 1 ? base : `${base} (${count})`;
}

function mapBackendLifecycle(payload: TerminalLifecyclePayload): TerminalLifecycle {
  if (payload.state === "started") return "working";
  if (payload.state === "failed") return "failed";
  return "exited";
}

function createId(prefix: string) {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}:${randomPart}`;
}

import { useCallback, useEffect, useRef, useState } from "react";

import {
  DEFAULT_WORKSPACE_ID,
  isTauriRuntime,
  listWorktrees,
  onWorktreeChanged,
  toIpcError,
} from "../lib/tauri";
import { ensureTerminalEvents } from "../lib/terminalEvents";
import type { StructuredIpcError, Worktree, WorktreeChangedPayload } from "../lib/types";

export type WorkspaceRuntimeServices = {
  ensureTerminalEvents: () => Promise<void>;
  listWorktrees: (workspaceId: string) => Promise<Worktree[]>;
  onWorktreeChanged: (handler: (payload: WorktreeChangedPayload) => void) => Promise<() => void>;
  isTauriRuntime: () => boolean;
};

type UseWorkspaceRuntimeOptions = {
  workspaceId?: string;
  activeWorktreePath: string | null;
  syncWorktrees: (worktrees: Worktree[]) => Promise<void>;
  ensureTabForWorktree: (worktree: Worktree) => Promise<string>;
  services?: WorkspaceRuntimeServices;
};

const defaultServices: WorkspaceRuntimeServices = {
  ensureTerminalEvents,
  listWorktrees,
  onWorktreeChanged,
  isTauriRuntime,
};

const PREVIEW_WORKTREE: Worktree = {
  path: ".",
  head: "main",
  branch: "refs/heads/main",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

export function useWorkspaceRuntime({
  workspaceId = DEFAULT_WORKSPACE_ID,
  activeWorktreePath,
  syncWorktrees,
  ensureTabForWorktree,
  services = defaultServices,
}: UseWorkspaceRuntimeOptions) {
  const [runtimeError, setRuntimeError] = useState<StructuredIpcError | null>(null);
  const activeWorktreePathRef = useRef(activeWorktreePath);
  const refreshInFlightRef = useRef<Promise<void> | null>(null);
  activeWorktreePathRef.current = activeWorktreePath;

  const reportRuntimeError = useCallback((error: unknown) => {
    setRuntimeError(toIpcError(error));
  }, []);

  const refreshWorktrees = useCallback(() => {
    if (refreshInFlightRef.current) return refreshInFlightRef.current;

    const refreshPromise = (async () => {
      try {
        const listed = await services.listWorktrees(workspaceId);
        const worktrees = listed.length > 0 || services.isTauriRuntime() ? listed : [PREVIEW_WORKTREE];
        await syncWorktrees(worktrees);
        const preferred = worktrees.find((worktree) => worktree.path === activeWorktreePathRef.current) ?? worktrees[0];
        if (preferred) await ensureTabForWorktree(preferred);
        setRuntimeError(null);
      } catch (error) {
        reportRuntimeError(error);
      }
    })().finally(() => {
      refreshInFlightRef.current = null;
    });

    refreshInFlightRef.current = refreshPromise;
    return refreshPromise;
  }, [ensureTabForWorktree, reportRuntimeError, services, syncWorktrees, workspaceId]);

  useEffect(() => {
    let disposed = false;
    let unlistenWorktreeChanged: (() => void) | undefined;

    const initialize = async () => {
      await services.ensureTerminalEvents();
      if (disposed) return;
      unlistenWorktreeChanged = await services.onWorktreeChanged(() => {
        void refreshWorktrees();
      });
      if (disposed) {
        unlistenWorktreeChanged();
        return;
      }
      await refreshWorktrees();
    };

    const handleFocus = () => {
      void refreshWorktrees();
    };

    window.addEventListener("focus", handleFocus);
    void initialize().catch(reportRuntimeError);

    return () => {
      disposed = true;
      window.removeEventListener("focus", handleFocus);
      unlistenWorktreeChanged?.();
    };
  }, [refreshWorktrees, reportRuntimeError, services]);

  return { runtimeError, refreshWorktrees, reportRuntimeError };
}

import type {
  LayoutState,
  TabGroup,
  TabGroupLayoutNode,
  TabPaneLayout,
  WorkspaceTab,
} from "../lib/types";
import {
  clampRatio,
  collectLeafIds,
  createLeafNode,
  equalizeRatios,
  findFirstLeafId,
  findSiblingLeafId,
  type PaneDirection,
  removeLeaf,
  setRatioAtPath,
  splitLeaf,
  swapLeaves,
} from "./paneTree";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: WorkspaceTab; sessionId?: string; activate?: boolean }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: WorkspaceTab }
  | { type: "ACTIVATE_TAB"; tabId: string }
  | { type: "REORDER_TAB"; tabId: string; targetIndex: number }
  | { type: "RENAME_TAB"; tabId: string; label: string }
  | { type: "SET_TAB_PINNED"; tabId: string; pinned: boolean }
  | {
      type: "SPLIT_PANE";
      tabId: string;
      targetLeafId?: string;
      direction: PaneDirection;
      newLeafId?: string;
      sessionId: string;
      position?: "first" | "second";
      ratio?: number;
    }
  | {
      type: "MOVE_TAB_TO_GROUP";
      sourceTabId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "MOVE_TAB_TO_SPLIT";
      sourceTabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position?: "first" | "second";
      ratio?: number;
    }
  | {
      type: "DETACH_PANE_TO_TAB";
      sourceTabId: string;
      leafId: string;
      newTab: WorkspaceTab;
      targetGroupId?: string;
      targetIndex?: number;
    }
  | { type: "SET_TAB_GROUP_RATIO"; path: string; ratio: number }
  | { type: "CLOSE_PANE"; tabId: string; leafId: string; replacementSessionId?: string }
  | { type: "FOCUS_PANE"; tabId: string; leafId: string }
  | { type: "SET_PANE_RATIO"; tabId: string; path: string; ratio: number }
  | { type: "SWAP_PANES"; tabId: string; sourceLeafId: string; targetLeafId: string }
  | { type: "TOGGLE_PANE_EXPANDED"; tabId: string; leafId: string }
  | { type: "EQUALIZE_PANES"; tabId: string };

export function createLayoutState(tabs: WorkspaceTab[] = [], activeTabId?: string | null): LayoutState {
  const layoutsByTabId: Record<string, TabPaneLayout> = {};
  for (const tab of tabs) {
    const leafId = "leaf-init";
    const sessionId = tab.kind === "browser" ? "" : tab.sessionId;
    layoutsByTabId[tab.id] = {
      root: createLeafNode(leafId),
      activeLeafId: leafId,
      expandedLeafId: null,
      sessionIdsByLeafId: { [leafId]: sessionId },
    };
  }

  return normalizeLayoutInternal(
    {
      tabs,
      activeTabId: activeTabId ?? tabs[0]?.id ?? null,
      layoutsByTabId,
    },
    true,
  );
}

export function getTabGroups(state: LayoutState): Record<string, TabGroup> {
  return normalizeLayout(state).tabGroups ?? {};
}

export function getTabGroupLayout(state: LayoutState): TabGroupLayoutNode | null {
  return normalizeLayout(state).tabGroupLayout ?? null;
}

export function getFocusedGroupId(state: LayoutState): string | null {
  return normalizeLayout(state).focusedGroupId ?? null;
}

export function getGroupForTab(state: LayoutState, tabId: string): TabGroup | null {
  const normalized = normalizeLayout(state);
  return findGroupContainingTab(normalized.tabGroups ?? {}, tabId);
}

export function getTabsForGroup(state: LayoutState, groupId: string): WorkspaceTab[] {
  const normalized = normalizeLayout(state);
  const group = normalized.tabGroups?.[groupId];
  if (!group) return [];
  const byId = new Map(normalized.tabs.map((tab) => [tab.id, tab]));
  return group.tabIds.map((tabId) => byId.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab));
}

export function layoutReducer(inputState: LayoutState, action: LayoutAction): LayoutState {
  const state = normalizeLayout(inputState);
  switch (action.type) {
    case "ADD_TAB": {
      const exists = state.tabs.some((tab) => tab.id === action.tab.id);
      const tabs = exists ? state.tabs : [...state.tabs, action.tab];
      const layoutsByTabId = { ...state.layoutsByTabId };
      if (!layoutsByTabId[action.tab.id]) {
        const leafId = createLayoutId("leaf");
        const defaultSessionId = action.tab.kind === "browser" ? "" : action.tab.sessionId;
        const sessionId = action.sessionId ?? defaultSessionId;
        layoutsByTabId[action.tab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: sessionId },
        };
      }
      return normalizeLayoutInternal(
        {
          ...state,
          tabs,
          activeTabId: action.activate === false ? state.activeTabId : action.tab.id,
          layoutsByTabId,
        },
        true,
      );
    }
    case "CLOSE_TAB": {
      const closingIndex = state.tabs.findIndex((tab) => tab.id === action.tabId);
      if (closingIndex < 0) return state;

      let tabs = state.tabs.filter((tab) => tab.id !== action.tabId);
      const layoutsByTabId = { ...state.layoutsByTabId };
      delete layoutsByTabId[action.tabId];

      if (tabs.length === 0 && action.replacementTab) {
        tabs = [action.replacementTab];
        const leafId = "leaf-replacement";
        const defaultSessionId = action.replacementTab.kind === "browser" ? "" : action.replacementTab.sessionId;
        layoutsByTabId[action.replacementTab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: defaultSessionId },
        };
      }

      let activeTabId = state.activeTabId;
      if (state.activeTabId === action.tabId) {
        activeTabId = tabs[Math.min(closingIndex, tabs.length - 1)]?.id ?? null;
      }
      return normalizeLayoutInternal({ ...state, tabs, activeTabId, layoutsByTabId }, true);
    }
    case "ACTIVATE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      const group = findGroupContainingTab(state.tabGroups ?? {}, action.tabId);
      if (!group) return normalizeLayoutInternal({ ...state, activeTabId: action.tabId }, true);
      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: action.tabId,
          focusedGroupId: group.id,
          tabGroups: {
            ...state.tabGroups,
            [group.id]: { ...group, activeTabId: action.tabId },
          },
        },
        true,
      );
    }
    case "REORDER_TAB": {
      const group = findGroupContainingTab(state.tabGroups ?? {}, action.tabId);
      if (!group || group.tabIds.length < 2 || !Number.isFinite(action.targetIndex)) return state;
      const sourceIndex = group.tabIds.indexOf(action.tabId);
      const targetIndex = Math.max(0, Math.min(group.tabIds.length - 1, Math.trunc(action.targetIndex)));
      if (sourceIndex === targetIndex) return state;
      const tabIds = [...group.tabIds];
      const [moved] = tabIds.splice(sourceIndex, 1);
      tabIds.splice(targetIndex, 0, moved);
      return normalizeLayoutInternal(
        {
          ...state,
          tabGroups: {
            ...state.tabGroups,
            [group.id]: { ...group, tabIds },
          },
        },
        true,
      );
    }
    case "RENAME_TAB": {
      const label = action.label.trim();
      if (!label || !state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          tabs: state.tabs.map((tab) => (tab.id === action.tabId ? { ...tab, label } : tab)),
        },
        true,
      );
    }
    case "SET_TAB_PINNED": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          tabs: state.tabs.map((tab) => (tab.id === action.tabId ? { ...tab, pinned: action.pinned } : tab)),
        },
        true,
      );
    }
    case "SPLIT_PANE": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const targetLeafId = action.targetLeafId ?? tabLayout.activeLeafId ?? findFirstLeafId(tabLayout.root);
      const existingLeafIds = collectLeafIds(tabLayout.root);
      if (!targetLeafId || !existingLeafIds.includes(targetLeafId)) return state;
      const newLeafId = action.newLeafId ?? createLayoutId("leaf");
      if (existingLeafIds.includes(newLeafId)) return state;
      const newRoot = splitLeaf(tabLayout.root, targetLeafId, newLeafId, action.direction, action.position, action.ratio);
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: {
              ...tabLayout,
              root: newRoot,
              activeLeafId: newLeafId,
              expandedLeafId: null,
              sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId, [newLeafId]: action.sessionId },
            },
          },
        },
        true,
      );
    }
    case "MOVE_TAB_TO_GROUP": {
      const sourceTab = state.tabs.find((tab) => tab.id === action.sourceTabId);
      const groups = { ...(state.tabGroups ?? {}) };
      const sourceGroup = findGroupContainingTab(groups, action.sourceTabId);
      const targetGroup = groups[action.targetGroupId];
      if (!sourceTab || !sourceGroup || !targetGroup || !Number.isFinite(action.targetIndex ?? 0)) return state;

      if (sourceGroup.id === targetGroup.id) {
        if (action.targetIndex === undefined || sourceGroup.tabIds.length < 2) return state;
        const sourceIndex = sourceGroup.tabIds.indexOf(sourceTab.id);
        const targetIndex = Math.max(0, Math.min(sourceGroup.tabIds.length - 1, Math.trunc(action.targetIndex)));
        if (sourceIndex === targetIndex) return state;
        const tabIds = [...sourceGroup.tabIds];
        tabIds.splice(sourceIndex, 1);
        tabIds.splice(targetIndex, 0, sourceTab.id);
        groups[sourceGroup.id] = { ...sourceGroup, tabIds, activeTabId: sourceTab.id };
        return normalizeLayoutInternal(
          { ...state, activeTabId: sourceTab.id, focusedGroupId: sourceGroup.id, tabGroups: groups },
          true,
        );
      }

      const sourceIndex = sourceGroup.tabIds.indexOf(sourceTab.id);
      const remainingSourceTabIds = sourceGroup.tabIds.filter((tabId) => tabId !== sourceTab.id);
      let tabGroupLayout = state.tabGroupLayout ?? null;
      if (remainingSourceTabIds.length === 0) {
        delete groups[sourceGroup.id];
        tabGroupLayout = removeTabGroupLeaf(tabGroupLayout, sourceGroup.id);
      } else {
        groups[sourceGroup.id] = {
          ...sourceGroup,
          tabIds: remainingSourceTabIds,
          activeTabId:
            sourceGroup.activeTabId === sourceTab.id || !remainingSourceTabIds.includes(sourceGroup.activeTabId ?? "")
              ? remainingSourceTabIds[Math.min(sourceIndex, remainingSourceTabIds.length - 1)] ?? remainingSourceTabIds[0]
              : sourceGroup.activeTabId,
        };
      }

      const liveTarget = groups[targetGroup.id];
      if (!liveTarget) return state;
      const insertionIndex = Math.max(
        0,
        Math.min(liveTarget.tabIds.length, Math.trunc(action.targetIndex ?? liveTarget.tabIds.length)),
      );
      const targetTabIds = [...liveTarget.tabIds];
      targetTabIds.splice(insertionIndex, 0, sourceTab.id);
      groups[liveTarget.id] = { ...liveTarget, tabIds: targetTabIds, activeTabId: sourceTab.id };

      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: sourceTab.id,
          focusedGroupId: liveTarget.id,
          tabGroups: groups,
          tabGroupLayout,
        },
        true,
      );
    }
    case "MOVE_TAB_TO_SPLIT": {
      const sourceTab = state.tabs.find((tab) => tab.id === action.sourceTabId);
      const groups = { ...(state.tabGroups ?? {}) };
      const sourceGroup = findGroupContainingTab(groups, action.sourceTabId);
      const targetGroup = groups[action.targetGroupId];
      if (!sourceTab || !sourceGroup || !targetGroup) return state;
      if (sourceGroup.id === targetGroup.id && sourceGroup.tabIds.length <= 1) return state;

      const sourceIndex = sourceGroup.tabIds.indexOf(sourceTab.id);
      const remainingSourceTabIds = sourceGroup.tabIds.filter((tabId) => tabId !== sourceTab.id);
      const nextSourceActive =
        remainingSourceTabIds[Math.min(sourceIndex, remainingSourceTabIds.length - 1)] ?? remainingSourceTabIds[0] ?? null;

      let tabGroupLayout = state.tabGroupLayout ?? null;
      if (remainingSourceTabIds.length === 0 && sourceGroup.id !== targetGroup.id) {
        delete groups[sourceGroup.id];
        tabGroupLayout = removeTabGroupLeaf(tabGroupLayout, sourceGroup.id);
      } else {
        groups[sourceGroup.id] = {
          ...sourceGroup,
          tabIds: remainingSourceTabIds,
          activeTabId:
            sourceGroup.activeTabId === sourceTab.id || !remainingSourceTabIds.includes(sourceGroup.activeTabId ?? "")
              ? nextSourceActive
              : sourceGroup.activeTabId,
        };
      }

      const newGroupId = createLayoutId("group");
      groups[newGroupId] = { id: newGroupId, tabIds: [sourceTab.id], activeTabId: sourceTab.id };
      tabGroupLayout = splitTabGroupLeaf(
        tabGroupLayout,
        targetGroup.id,
        newGroupId,
        action.direction,
        action.position,
        action.ratio,
      );

      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: sourceTab.id,
          focusedGroupId: newGroupId,
          tabGroups: groups,
          tabGroupLayout,
        },
        true,
      );
    }
    case "DETACH_PANE_TO_TAB": {
      const sourceTab = state.tabs.find((tab) => tab.id === action.sourceTabId);
      const sourceLayout = state.layoutsByTabId[action.sourceTabId];
      const sourceGroup = findGroupContainingTab(state.tabGroups ?? {}, action.sourceTabId);
      if (
        !sourceTab ||
        sourceTab.kind === "browser" ||
        !sourceLayout ||
        !sourceGroup ||
        state.tabs.some((tab) => tab.id === action.newTab.id)
      ) {
        return state;
      }
      const leafIds = collectLeafIds(sourceLayout.root);
      if (leafIds.length <= 1 || !leafIds.includes(action.leafId)) return state;
      const movedSessionId = sourceLayout.sessionIdsByLeafId[action.leafId];
      if (!movedSessionId || action.newTab.kind === "browser") return state;

      const nextRoot = removeLeaf(sourceLayout.root, action.leafId);
      if (!nextRoot) return state;
      const fallbackLeafId = findSiblingLeafId(sourceLayout.root, action.leafId) ?? findFirstLeafId(nextRoot);
      const nextSessionIdsByLeafId = { ...sourceLayout.sessionIdsByLeafId };
      delete nextSessionIdsByLeafId[action.leafId];
      const nextPrimarySessionId =
        sourceTab.sessionId === movedSessionId
          ? nextSessionIdsByLeafId[fallbackLeafId] ?? Object.values(nextSessionIdsByLeafId)[0] ?? sourceTab.sessionId
          : sourceTab.sessionId;
      const nextSourceTab = { ...sourceTab, sessionId: nextPrimarySessionId };
      const newTab = { ...action.newTab, sessionId: movedSessionId };
      const targetGroupId = action.targetGroupId ?? sourceGroup.id;
      const targetGroup = state.tabGroups?.[targetGroupId];
      if (!targetGroup) return state;

      const groups = { ...(state.tabGroups ?? {}) };
      const liveTarget = groups[targetGroupId];
      const defaultIndex = targetGroupId === sourceGroup.id
        ? sourceGroup.tabIds.indexOf(sourceTab.id) + 1
        : liveTarget.tabIds.length;
      const insertionIndex = Math.max(
        0,
        Math.min(liveTarget.tabIds.length, Math.trunc(action.targetIndex ?? defaultIndex)),
      );
      const targetTabIds = [...liveTarget.tabIds];
      targetTabIds.splice(insertionIndex, 0, newTab.id);
      groups[targetGroupId] = { ...liveTarget, tabIds: targetTabIds, activeTabId: newTab.id };

      return normalizeLayoutInternal(
        {
          ...state,
          tabs: [...state.tabs.map((tab) => (tab.id === sourceTab.id ? nextSourceTab : tab)), newTab],
          activeTabId: newTab.id,
          focusedGroupId: targetGroupId,
          tabGroups: groups,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [sourceTab.id]: {
              ...sourceLayout,
              root: nextRoot,
              activeLeafId: sourceLayout.activeLeafId === action.leafId ? fallbackLeafId : sourceLayout.activeLeafId,
              expandedLeafId: sourceLayout.expandedLeafId === action.leafId ? null : sourceLayout.expandedLeafId,
              sessionIdsByLeafId: nextSessionIdsByLeafId,
            },
            [newTab.id]: {
              root: createLeafNode(action.leafId),
              activeLeafId: action.leafId,
              expandedLeafId: null,
              sessionIdsByLeafId: { [action.leafId]: movedSessionId },
            },
          },
        },
        true,
      );
    }
    case "SET_TAB_GROUP_RATIO": {
      if (!state.tabGroupLayout) return state;
      const nextLayout = setTabGroupRatioAtPath(state.tabGroupLayout, action.path, action.ratio);
      if (nextLayout === state.tabGroupLayout) return state;
      return normalizeLayoutInternal({ ...state, tabGroupLayout: nextLayout }, true);
    }
    case "CLOSE_PANE": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const leafIds = collectLeafIds(tabLayout.root);
      if (!leafIds.includes(action.leafId)) return state;
      const fallbackLeafId = findSiblingLeafId(tabLayout.root, action.leafId);
      const newRoot = removeLeaf(tabLayout.root, action.leafId);
      if (!newRoot) return layoutReducer(state, { type: "CLOSE_TAB", tabId: action.tabId });
      const newSessionIds = { ...tabLayout.sessionIdsByLeafId };
      delete newSessionIds[action.leafId];
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: {
              ...tabLayout,
              root: newRoot,
              activeLeafId:
                tabLayout.activeLeafId === action.leafId
                  ? fallbackLeafId ?? findFirstLeafId(newRoot)
                  : tabLayout.activeLeafId,
              expandedLeafId: tabLayout.expandedLeafId === action.leafId ? null : tabLayout.expandedLeafId,
              sessionIdsByLeafId: newSessionIds,
            },
          },
        },
        true,
      );
    }
    case "FOCUS_PANE": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout || !collectLeafIds(tabLayout.root).includes(action.leafId)) return state;
      const group = findGroupContainingTab(state.tabGroups ?? {}, action.tabId);
      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: action.tabId,
          focusedGroupId: group?.id ?? state.focusedGroupId,
          tabGroups: group
            ? { ...state.tabGroups, [group.id]: { ...group, activeTabId: action.tabId } }
            : state.tabGroups,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, activeLeafId: action.leafId },
          },
        },
        true,
      );
    }
    case "SET_PANE_RATIO": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const root = setRatioAtPath(tabLayout.root, action.path, action.ratio);
      if (root === tabLayout.root) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, root },
          },
        },
        true,
      );
    }
    case "SWAP_PANES": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const root = swapLeaves(tabLayout.root, action.sourceLeafId, action.targetLeafId);
      if (root === tabLayout.root) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, root },
          },
        },
        true,
      );
    }
    case "TOGGLE_PANE_EXPANDED": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout || !collectLeafIds(tabLayout.root).includes(action.leafId)) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: {
              ...tabLayout,
              expandedLeafId: tabLayout.expandedLeafId === action.leafId ? null : action.leafId,
            },
          },
        },
        true,
      );
    }
    case "EQUALIZE_PANES": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const root = equalizeRatios(tabLayout.root);
      if (root === tabLayout.root) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, root },
          },
        },
        true,
      );
    }
  }
}

export function normalizeLayout(state: LayoutState): LayoutState {
  return normalizeLayoutInternal(state, false);
}

function normalizeLayoutInternal(state: LayoutState, force: boolean): LayoutState {
  if (!force && isNormalizedLayoutState(state)) return state;

  const dedupedTabs = dedupeTabs(state.tabs);
  if (dedupedTabs.length === 0) {
    if (
      state.tabs.length === 0 &&
      state.activeTabId === null &&
      Object.keys(state.layoutsByTabId).length === 0 &&
      state.tabGroupLayout === null &&
      state.focusedGroupId === null &&
      Object.keys(state.tabGroups ?? {}).length === 0
    ) {
      return state;
    }
    return {
      ...state,
      tabs: [],
      activeTabId: null,
      layoutsByTabId: {},
      tabGroups: {},
      tabGroupLayout: null,
      focusedGroupId: null,
    };
  }

  const validTabIds = new Set(dedupedTabs.map((tab) => tab.id));
  const nextLayoutsByTabId: Record<string, TabPaneLayout> = {};
  let paneLayoutsChanged = Object.keys(state.layoutsByTabId).length !== dedupedTabs.length;
  for (const tab of dedupedTabs) {
    const existing = state.layoutsByTabId[tab.id];
    if (existing) {
      const leaves = collectLeafIds(existing.root);
      const activeLeafId = leaves.includes(existing.activeLeafId ?? "") ? existing.activeLeafId : leaves[0] ?? null;
      const expandedLeafId = leaves.includes(existing.expandedLeafId ?? "") ? existing.expandedLeafId : null;
      const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
      const existingSessionKeys = Object.keys(existing.sessionIdsByLeafId);
      const mappingIsExact =
        existingSessionKeys.length === leaves.length &&
        leaves.every((leafId) => Object.prototype.hasOwnProperty.call(existing.sessionIdsByLeafId, leafId));
      if (activeLeafId === existing.activeLeafId && expandedLeafId === existing.expandedLeafId && mappingIsExact) {
        nextLayoutsByTabId[tab.id] = existing;
      } else {
        paneLayoutsChanged = true;
        nextLayoutsByTabId[tab.id] = {
          ...existing,
          activeLeafId,
          expandedLeafId,
          sessionIdsByLeafId: Object.fromEntries(
            leaves.map((leafId) => [leafId, existing.sessionIdsByLeafId[leafId] ?? defaultSessionId]),
          ),
        };
      }
    } else {
      paneLayoutsChanged = true;
      const leafId = createLayoutId("leaf-default");
      const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
      nextLayoutsByTabId[tab.id] = {
        root: createLeafNode(leafId),
        activeLeafId: leafId,
        expandedLeafId: null,
        sessionIdsByLeafId: { [leafId]: defaultSessionId },
      };
    }
  }
  const layoutsByTabId = paneLayoutsChanged ? nextLayoutsByTabId : state.layoutsByTabId;

  const incomingGroups = state.tabGroups ?? {};
  const groups: Record<string, TabGroup> = {};
  const assigned = new Set<string>();
  for (const [groupId, group] of Object.entries(incomingGroups)) {
    const tabIds = group.tabIds.filter((tabId) => validTabIds.has(tabId) && !assigned.has(tabId));
    if (tabIds.length === 0) continue;
    tabIds.forEach((tabId) => assigned.add(tabId));
    groups[groupId] = {
      id: groupId,
      tabIds,
      activeTabId: tabIds.includes(group.activeTabId ?? "") ? group.activeTabId : tabIds[0],
    };
  }

  let tabGroupLayout = pruneTabGroupLayout(state.tabGroupLayout ?? null, new Set(Object.keys(groups)));
  if (Object.keys(groups).length === 0) {
    const groupId = "group-default";
    groups[groupId] = {
      id: groupId,
      tabIds: dedupedTabs.map((tab) => tab.id),
      activeTabId: validTabIds.has(state.activeTabId ?? "") ? state.activeTabId : dedupedTabs[0].id,
    };
    dedupedTabs.forEach((tab) => assigned.add(tab.id));
    tabGroupLayout = { type: "group", groupId };
  }

  let focusedGroupId =
    state.focusedGroupId && groups[state.focusedGroupId]
      ? state.focusedGroupId
      : findGroupContainingTab(groups, state.activeTabId ?? "")?.id ?? findFirstTabGroupId(tabGroupLayout);
  if (!focusedGroupId || !groups[focusedGroupId]) focusedGroupId = Object.keys(groups)[0] ?? null;

  const unassigned = dedupedTabs.map((tab) => tab.id).filter((tabId) => !assigned.has(tabId));
  if (unassigned.length > 0 && focusedGroupId) {
    groups[focusedGroupId] = {
      ...groups[focusedGroupId],
      tabIds: [...groups[focusedGroupId].tabIds, ...unassigned],
    };
    unassigned.forEach((tabId) => assigned.add(tabId));
  }

  for (const groupId of Object.keys(groups)) {
    if (!containsTabGroup(tabGroupLayout, groupId)) {
      tabGroupLayout = appendTabGroupLayout(tabGroupLayout, { type: "group", groupId });
    }
  }
  tabGroupLayout = pruneTabGroupLayout(tabGroupLayout, new Set(Object.keys(groups)));

  if (focusedGroupId) {
    const focused = groups[focusedGroupId];
    if (focused && focused.tabIds.includes(state.activeTabId ?? "")) {
      groups[focusedGroupId] = { ...focused, activeTabId: state.activeTabId };
    }
  }

  const focusedGroup = focusedGroupId ? groups[focusedGroupId] : null;
  const activeTabId = focusedGroup?.activeTabId ?? dedupedTabs[0].id;
  const tabById = new Map(dedupedTabs.map((tab) => [tab.id, tab]));
  const flattenedIds = flattenTabIds(tabGroupLayout, groups);
  const tabs = flattenedIds.map((tabId) => tabById.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab));
  for (const tab of dedupedTabs) if (!flattenedIds.includes(tab.id)) tabs.push(tab);

  return {
    ...state,
    tabs,
    activeTabId,
    layoutsByTabId,
    tabGroups: groups,
    tabGroupLayout,
    focusedGroupId,
  };
}

function isNormalizedLayoutState(state: LayoutState): boolean {
  if (state.tabs.length === 0) {
    return (
      state.activeTabId === null &&
      Object.keys(state.layoutsByTabId).length === 0 &&
      state.tabGroupLayout === null &&
      state.focusedGroupId === null &&
      Object.keys(state.tabGroups ?? {}).length === 0
    );
  }
  if (!state.tabGroups || !state.tabGroupLayout || !state.focusedGroupId || !state.tabGroups[state.focusedGroupId]) return false;
  const valid = new Set(state.tabs.map((tab) => tab.id));
  const assigned = new Set<string>();
  for (const group of Object.values(state.tabGroups)) {
    if (group.tabIds.length === 0 || !containsTabGroup(state.tabGroupLayout, group.id)) return false;
    if (!group.activeTabId || !group.tabIds.includes(group.activeTabId)) return false;
    for (const tabId of group.tabIds) {
      if (!valid.has(tabId) || assigned.has(tabId)) return false;
      assigned.add(tabId);
    }
  }
  if (assigned.size !== valid.size) return false;
  return state.tabs.every((tab) => Boolean(state.layoutsByTabId[tab.id]));
}

function findGroupContainingTab(groups: Record<string, TabGroup>, tabId: string): TabGroup | null {
  if (!tabId) return null;
  return Object.values(groups).find((group) => group.tabIds.includes(tabId)) ?? null;
}

function splitTabGroupLeaf(
  root: TabGroupLayoutNode | null,
  targetGroupId: string,
  newGroupId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") {
    if (root.groupId !== targetGroupId) return root;
    const added: TabGroupLayoutNode = { type: "group", groupId: newGroupId };
    return {
      type: "split",
      direction,
      first: position === "first" ? added : root,
      second: position === "first" ? root : added,
      ratio: clampRatio(ratio),
    };
  }
  const first = splitTabGroupLeaf(root.first, targetGroupId, newGroupId, direction, position, ratio);
  if (first !== root.first) return { ...root, first: first ?? root.first };
  const second = splitTabGroupLeaf(root.second, targetGroupId, newGroupId, direction, position, ratio);
  if (second !== root.second) return { ...root, second: second ?? root.second };
  return root;
}

function removeTabGroupLeaf(root: TabGroupLayoutNode | null, groupId: string): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") return root.groupId === groupId ? null : root;
  const first = removeTabGroupLeaf(root.first, groupId);
  if (!first) return root.second;
  if (first !== root.first) return { ...root, first };
  const second = removeTabGroupLeaf(root.second, groupId);
  if (!second) return root.first;
  if (second !== root.second) return { ...root, second };
  return root;
}

function pruneTabGroupLayout(root: TabGroupLayoutNode | null, validGroupIds: Set<string>): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") return validGroupIds.has(root.groupId) ? root : null;
  const first = pruneTabGroupLayout(root.first, validGroupIds);
  const second = pruneTabGroupLayout(root.second, validGroupIds);
  if (!first) return second;
  if (!second) return first;
  if (first === root.first && second === root.second) return root;
  return { ...root, first, second };
}

function appendTabGroupLayout(first: TabGroupLayoutNode | null, second: TabGroupLayoutNode): TabGroupLayoutNode {
  if (!first) return second;
  return { type: "split", direction: "horizontal", first, second, ratio: 0.5 };
}

function containsTabGroup(root: TabGroupLayoutNode | null, groupId: string): boolean {
  if (!root) return false;
  if (root.type === "group") return root.groupId === groupId;
  return containsTabGroup(root.first, groupId) || containsTabGroup(root.second, groupId);
}

function findFirstTabGroupId(root: TabGroupLayoutNode | null): string | null {
  if (!root) return null;
  let node = root;
  while (node.type === "split") node = node.first;
  return node.groupId;
}

function flattenTabIds(root: TabGroupLayoutNode | null, groups: Record<string, TabGroup>): string[] {
  if (!root) return [];
  if (root.type === "group") return groups[root.groupId]?.tabIds ?? [];
  return [...flattenTabIds(root.first, groups), ...flattenTabIds(root.second, groups)];
}

function setTabGroupRatioAtPath(root: TabGroupLayoutNode, path: string, ratio: number): TabGroupLayoutNode {
  const segments = path.split(".").filter(Boolean);
  const visit = (node: TabGroupLayoutNode, remaining: string[]): TabGroupLayoutNode => {
    if (node.type === "group") return node;
    if (remaining.length === 0) {
      const nextRatio = clampRatio(ratio);
      return node.ratio === nextRatio ? node : { ...node, ratio: nextRatio };
    }
    const [head, ...rest] = remaining;
    if (head !== "first" && head !== "second") return node;
    const child = visit(node[head], rest);
    return child === node[head] ? node : { ...node, [head]: child };
  };
  return visit(root, segments);
}

function dedupeTabs(tabs: WorkspaceTab[]) {
  const seen = new Set<string>();
  return tabs.filter((tab) => {
    if (seen.has(tab.id)) return false;
    seen.add(tab.id);
    return true;
  });
}

function createLayoutId(prefix: string) {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}:${randomPart}`;
}

export type PaneDirection = "horizontal" | "vertical";

export type PaneLeafNode = { type: "leaf"; leafId: string };

export type PaneSplitNode = {
  type: "split";
  direction: PaneDirection;
  first: PaneNode;
  second: PaneNode;
  ratio: number;
};

export type PaneNode = PaneLeafNode | PaneSplitNode;

export const MIN_PANE_RATIO = 0.1;
export const MAX_PANE_RATIO = 0.9;

/** Clamps a ratio into the usable range, falling back to an even split for non-finite input. */
export function clampRatio(ratio: number): number {
  if (!Number.isFinite(ratio)) return 0.5;
  return Math.min(MAX_PANE_RATIO, Math.max(MIN_PANE_RATIO, ratio));
}

export function createLeafNode(leafId?: string): PaneNode {
  return { type: "leaf", leafId: leafId ?? createLeafId() };
}

/**
 * Replaces the leaf `targetLeafId` with a split containing that leaf and a new leaf.
 * `position` decides which side the new leaf takes. Returns the original tree when
 * the target leaf does not exist.
 */
export function splitLeaf(
  root: PaneNode,
  targetLeafId: string,
  newLeafId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return splitLeafWithSubtree(root, targetLeafId, createLeafNode(newLeafId), direction, position, ratio);
}

/**
 * Replaces `targetLeafId` with a split containing the existing target leaf and an
 * arbitrary pane subtree. This is the pane-tree equivalent of Orca moving a whole
 * tab (including any terminal panes owned by that tab) into a newly-created split group.
 */
export function splitLeafWithSubtree(
  root: PaneNode,
  targetLeafId: string,
  subtree: PaneNode,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return mapLeaf(root, targetLeafId, (leaf) => ({
    type: "split",
    direction,
    first: position === "first" ? subtree : leaf,
    second: position === "first" ? leaf : subtree,
    ratio: clampRatio(ratio),
  }));
}

/**
 * Removes the leaf `targetLeafId`, collapsing its parent split into the surviving sibling.
 * Returns `null` when the removed leaf was the whole tree, and the original tree when the
 * leaf does not exist.
 */
export function removeLeaf(root: PaneNode, targetLeafId: string): PaneNode | null {
  if (root.type === "leaf") return root.leafId === targetLeafId ? null : root;

  const first = removeLeaf(root.first, targetLeafId);
  if (first === null) return root.second;
  if (first !== root.first) return { ...root, first };

  const second = removeLeaf(root.second, targetLeafId);
  if (second === null) return root.first;
  if (second !== root.second) return { ...root, second };

  return root;
}

/**
 * Sets the ratio of the split addressed by a dot-notation `path` such as "" (root),
 * "first", or "second.first". Returns the original tree when the path does not resolve
 * to a split node.
 */
export function setRatioAtPath(root: PaneNode, path: string, ratio: number): PaneNode {
  const segments = path.split(".").filter((segment) => segment.length > 0);
  return applyRatio(root, segments, clampRatio(ratio));
}

export function findFirstLeafId(root: PaneNode): string {
  let node = root;
  while (node.type === "split") node = node.first;
  return node.leafId;
}

export function collectLeafIds(root: PaneNode): string[] {
  const ids: string[] = [];
  const visit = (node: PaneNode) => {
    if (node.type === "leaf") {
      ids.push(node.leafId);
      return;
    }
    visit(node.first);
    visit(node.second);
  };
  visit(root);
  return ids;
}

/**
 * Returns the first leaf id inside the sibling subtree of `targetLeafId`,
 * or `null` when the leaf is missing or is the tree root.
 */
export function findSiblingLeafId(root: PaneNode, targetLeafId: string): string | null {
  if (root.type === "leaf") return null;

  const inFirst = containsLeaf(root.first, targetLeafId);
  const inSecond = containsLeaf(root.second, targetLeafId);

  if (inFirst) {
    return root.first.type === "leaf"
      ? findFirstLeafId(root.second)
      : findSiblingLeafId(root.first, targetLeafId);
  }
  if (inSecond) {
    return root.second.type === "leaf"
      ? findFirstLeafId(root.first)
      : findSiblingLeafId(root.second, targetLeafId);
  }
  return null;
}

/**
 * Swaps the positions of two leaves. Returns the original tree when either leaf is
 * missing or when both ids refer to the same leaf.
 */
export function swapLeaves(root: PaneNode, sourceLeafId: string, targetLeafId: string): PaneNode {
  if (sourceLeafId === targetLeafId) return root;
  if (!containsLeaf(root, sourceLeafId) || !containsLeaf(root, targetLeafId)) return root;

  const swap = (node: PaneNode): PaneNode => {
    if (node.type === "leaf") {
      if (node.leafId === sourceLeafId) return { type: "leaf", leafId: targetLeafId };
      if (node.leafId === targetLeafId) return { type: "leaf", leafId: sourceLeafId };
      return node;
    }
    const first = swap(node.first);
    const second = swap(node.second);
    if (first === node.first && second === node.second) return node;
    return { ...node, first, second };
  };

  return swap(root);
}

/** Resets every split in the tree to an even 0.5 ratio. */
export function equalizeRatios(root: PaneNode): PaneNode {
  if (root.type === "leaf") return root;
  const first = equalizeRatios(root.first);
  const second = equalizeRatios(root.second);
  if (first === root.first && second === root.second && root.ratio === 0.5) return root;
  return { ...root, first, second, ratio: 0.5 };
}

function applyRatio(node: PaneNode, segments: string[], ratio: number): PaneNode {
  if (node.type === "leaf") return node;

  if (segments.length === 0) {
    return node.ratio === ratio ? node : { ...node, ratio };
  }

  const [head, ...rest] = segments;
  if (head !== "first" && head !== "second") return node;

  const child = applyRatio(node[head], rest, ratio);
  if (child === node[head]) return node;
  return { ...node, [head]: child };
}

function mapLeaf(node: PaneNode, targetLeafId: string, replace: (leaf: PaneLeafNode) => PaneNode): PaneNode {
  if (node.type === "leaf") return node.leafId === targetLeafId ? replace(node) : node;

  const first = mapLeaf(node.first, targetLeafId, replace);
  if (first !== node.first) return { ...node, first };

  const second = mapLeaf(node.second, targetLeafId, replace);
  if (second !== node.second) return { ...node, second };

  return node;
}

function containsLeaf(node: PaneNode, leafId: string): boolean {
  if (node.type === "leaf") return node.leafId === leafId;
  return containsLeaf(node.first, leafId) || containsLeaf(node.second, leafId);
}

function createLeafId() {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `pane:${randomPart}`;
}

import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { installSettingsRuntimeBridge } from "./lib/settingsRuntimeBridge";
import { applyCachedTerminalBackground } from "./lib/terminalSettings";
import { RemoteApp } from "./remote/RemoteApp";
import "./index.css";
import "./settings-runtime.css";

installSettingsRuntimeBridge();
applyCachedTerminalBackground();

const isTauriApp = typeof window !== "undefined" && Boolean((window as any).__TAURI_INTERNALS__);

ReactDOM.createRoot(document.getElementById("root") as HTMLElement).render(
  <React.StrictMode>
    {isTauriApp ? <App /> : <RemoteApp />}
  </React.StrictMode>
);

if (typeof window !== "undefined" && "serviceWorker" in navigator && !isTauriApp) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch(() => {});
  });
}

